create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in standard SQL DATE dayofweek, or check against ISO week start)
    -- Using TO_CHAR(l_day, 'D') or similar can be tricky due to NLS settings.
    -- A reliable way is to check if the day of the week is Saturday (7) or Sunday (1) if using NLS_TERRITORY=AMERICA,
    -- or check if it's not the last day of the ISO week (which is Sunday).
    -- A simpler check for Mon-Fri is to check if the day number (1=Sunday, 7=Saturday) is not 1 or 7.
    -- Oracle's standard DAYOFWEEK returns 1 for Sunday, 7 for Saturday.
    if to_char(l_day, 'D') not in ('1', '7') then
      l_count := l_count + 1;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
